      "text": "Евгения живёт в доме богатого, но крайне скупого отца и почти не знает иной жизни, пока приезд разорившегося кузена из Парижа не пробуждает в ней любовь и желание помочь. Её щедрость сталкивается с семейным порядком, основанным на накоплении, превращая частное чувство в испытание власти денег над близостью и человеческим выбором.",
